import 'package:sqlite_async/sqlite_async.dart';

void main() async {
  final db = SqliteDatabase(path: 'test.db');
  await db.execute('CREATE TABLE IF NOT EXISTS test_data(id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT)');
  await db.execute('INSERT INTO test_data(data) values(?)', ['Test1']);
  var results = await db.getAll('SELECT * FROM test_data');
  print('Results: $results');
  await db.close();
}
